pos0 = np.asarray(t.xyz[0], dtype=np.float64)
bonds = [(b[0].index, b[1].index) for b in t.topology.bonds]

def run(pairs, move_second=True):
    pos = pos0.copy()
    for a1, a2 in pairs:
        delta = pos[a2] - pos[a1]
        offset = uc[2]*np.round(delta[2]/uc[2,2])
        offset = offset + uc[1]*np.round((delta[1]-offset[1])/uc[1,1])
        offset = offset + uc[0]*np.round((delta[0]-offset[0])/uc[0,0])
        if move_second:
            pos[a2] -= offset
        else:
            pos[a1] += offset
    bl = [np.linalg.norm(pos[a]-pos[b]) for a,b in bonds]
    return max(bl)

variants = {}
for swap in (False, True):
    prs = [(b, a) if swap else (a, b) for a, b in bonds]
    for key in (0, 1):
        for rev in (False, True):
            for move_second in (True, False):
                sp = sorted(prs, key=lambda p: p[key], reverse=rev)
                name = f"swap={swap} key={key} rev={rev} move_second={move_second}"
                variants[name] = run(sp, move_second)
for k, v in variants.items():
    print(f"{v:8.4f}  {k}")
